import click
from click.testing import CliRunner
r = CliRunner()

class AliasedGroup(click.Group):
    def get_command(self, ctx, cmd_name):
        return super().get_command(ctx, {"alias": "real"}.get(cmd_name, cmd_name))

@click.group(cls=AliasedGroup)
def cli(): pass

@cli.command()
@click.option("--flag", is_flag=True)
def real(flag): click.echo("flag=%r" % flag)

for dm in ({"real": {"flag": True}}, {"alias": {"flag": True}}):
    res = r.invoke(cli, ["alias"], default_map=dm)
    print(dm, "->", repr(res.output), res.exit_code, res.exception)
PY
